// Des: Tests for Marketplace list, renew, sold and the ledger
// Flo: list > ledger row with exact title, group, time > duplicate refused > renew and sold hit the right listing > unknown title = NoElement
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-mark-list-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const mark = @import("ru-mark-list.zig");
test "list fills the form, publishes once, writes the ledger" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); cx.now_fix = 5000000; const aa: task.Args = .{ .title = "Xe đạp Thống Nhất", .price = "2000000", .desc = "Còn mới 90%", .group = "Chợ xe HN" }; try std.testing.expectEqual(task.Out.done, try mark.listRun(&cx, aa)); try std.testing.expectEqualStrings("Xe đạp Thống Nhất|2000000|Còn mới 90%|0", rig.waitRec("list", 3000).?); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const rows = try rig.store.ledgList(aren.allocator()); try std.testing.expectEqual(@as(usize, 1), rows.len); try std.testing.expectEqualStrings("Xe đạp Thống Nhất", rows[0].titl); try std.testing.expectEqualStrings("Chợ xe HN", rows[0].grou); try std.testing.expectEqualStrings("L1001", rows[0].lid); try std.testing.expectEqual(@as(i64, 5000000), rows[0].pms); try std.testing.expectEqualStrings("live", rows[0].st); try std.testing.expectEqual(task.Out.dupe, try mark.listRun(&cx, aa)); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("list")); }
test "mark sold hits the matching listing and updates the ledger" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.store.ledgAdd("L2", "Blue desk", "Home goods", 1000); var cx = rig.ctx(.live); cx.now_fix = 9000; try std.testing.expectEqual(task.Out.done, try mark.soldRun(&cx, .{ .title = "blue DESK" })); try std.testing.expectEqualStrings("Blue desk", rig.waitRec("sold", 3000).?); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const rows = try rig.store.ledgList(aren.allocator()); try std.testing.expectEqualStrings("sold", rows[0].st); try std.testing.expectEqual(@as(i64, 9000), rows[0].ums); }
test "renew picks the first listing by index" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try mark.renewRun(&cx, .{ .title = "Red bike" })); try std.testing.expectEqualStrings("Red bike", rig.waitRec("renew", 3000).?); try std.testing.expectEqual(task.Out.dupe, try mark.renewRun(&cx, .{ .title = "Red bike" })); }
test "unknown title gives NoElement and writes nothing" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.NoElement, mark.soldRun(&cx, .{ .title = "No such item" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expectError(error.BadUsage, mark.soldRun(&cx, .{})); try std.testing.expectError(error.BadUsage, mark.listRun(&cx, .{ .title = "x" })); }
test "marketplace cap blocks the third action of the day" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_mark_dayz = 1; var cx = rig.ctx(.live); _ = try mark.renewRun(&cx, .{ .title = "Red bike" }); try std.testing.expectError(error.CapHit, mark.renewRun(&cx, .{ .title = "Blue desk" })); }
test "dry-run lists nothing and writes no ledger row" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.dry); try std.testing.expectEqual(task.Out.dry, try mark.listRun(&cx, .{ .title = "Lamp", .price = "100" })); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectEqual(@as(usize, 0), (try rig.store.ledgList(aren.allocator())).len); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
